const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = ee.Date('2024-11-01');
    const end = ee.Date('2024-12-01');
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1')
      .filter(ee.Filter.eq('ADM0_NAME', 'India'));
    const punjab = gaul.filter(ee.Filter.eq('ADM1_NAME', 'Punjab')).geometry();
    const haryana = gaul.filter(ee.Filter.eq('ADM1_NAME', 'Haryana')).geometry();
    const region = punjab.union(haryana, 1);

    // 2. Data Acquisition & Check
    // Try likely FIRMS VIIRS Active Fire datasets (archive then NRT)
    const candidateFCs = [
      'FIRMS/NOAA/VIIRS/V1/VNP14IMGTDL',
      'FIRMS/NOAA/VIIRS/V1/VNP14IMGTDL_NRT'
    ];

    let usedId = null;
    let detectionsFC = null;
    let totalCount = null;
    let datasetErrorCount = 0;

    for (const id of candidateFCs) {
      try {
        const fc = ee.FeatureCollection(id);
        // Basic existence check (unfiltered)
        await fc.limit(1).size().getInfo();
        // Apply filters
        const filtered = fc.filterBounds(region).filterDate(start, end);
        const count = await filtered.size().getInfo();
        if (count > 0) {
          usedId = id;
          detectionsFC = filtered;
          totalCount = count;
          break;
        } else {
          // Collection exists but no features in time/region -> might still be valid; keep as candidate.
          if (usedId === null) {
            usedId = id;
            detectionsFC = filtered;
            totalCount = count;
          }
        }
      } catch (e) {
        datasetErrorCount += 1;
        continue;
      }
    }

    if (datasetErrorCount === candidateFCs.length) {
      console.log('Dataset error: Unable to access FIRMS VIIRS datasets tried.');
      console.log('D');
      return;
    }

    if (totalCount === 0) {
      console.log(`Dataset used: ${usedId}`);
      console.log('Total detections (Nov 2024, Punjab+Haryana): 0');
      console.log('C1');
      return;
    }

    // 3. Processing: per-state counts
    const punjabCount = await detectionsFC.filterBounds(punjab).size().getInfo();
    const haryanaCount = await detectionsFC.filterBounds(haryana).size().getInfo();

    // 4. Validation & Final Answer
    const vals = [totalCount, punjabCount, haryanaCount];
    const anyNull = vals.some(v => v === null || v === undefined || isNaN(v));
    if (anyNull) {
      console.log('Calculation failure: null/NaN encountered.');
      console.log('C3');
      return;
    }

    // Evidence output (concise, <=20 lines)
    console.log(`Dataset used: ${usedId}`);
    console.log(`Date range: ${start.format('YYYY-MM-dd').getInfo()} to ${end.format('YYYY-MM-dd').getInfo()} (exclusive end)`);
    console.log(`Punjab detections: ${punjabCount}`);
    console.log(`Haryana detections: ${haryanaCount}`);
    console.log(`Total detections (Nov 2024, Punjab+Haryana): ${totalCount}`);

    // Threshold check
    const threshold = 20000;
    if (totalCount < threshold) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    // Any unexpected error
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
